 cx.beginPath();cx.roundRect(76,7,208,31,7);cx.fill();cx.stroke();
 cx.fillStyle='#efe4f8';cx.font='bold 9px system-ui,sans-serif';cx.textAlign='left';cx.fillText('GARDIEN K-17',85,20);
